package com.evfleet.backend.model;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant;
import jakarta.validation.constraints.*;
@Entity @Table(name="charging_stations",indexes=@Index(name="idx_stations_owner",columnList="owner_user_id"))
public class ChargingStation {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="owner_user_id") private Long ownerUserId; @NotBlank @Size(max=140) @Column(nullable=false,length=140) private String stationName; @NotBlank @Size(max=20) @Column(nullable=false,length=20) private String providerType; @NotBlank @Size(max=20) @Column(nullable=false,length=20) private String accessType; @NotBlank @Column(nullable=false) private String address; @NotNull @DecimalMin("-90.0") @DecimalMax("90.0") @Column(nullable=false,precision=9,scale=6) private BigDecimal latitude; @NotNull @DecimalMin("-180.0") @DecimalMax("180.0") @Column(nullable=false,precision=9,scale=6) private BigDecimal longitude; @NotBlank @Size(max=40) @Column(nullable=false,length=40) private String connectorType; @NotNull @Positive @Column(nullable=false,precision=7,scale=2) private BigDecimal powerKw; @PositiveOrZero @Column(precision=8,scale=2) private BigDecimal pricePerKwh; private boolean active=true; private Instant createdAt=Instant.now();
 public ChargingStation(){} public Long getId(){return id;} public Long getOwnerUserId(){return ownerUserId;} public void setOwnerUserId(Long v){ownerUserId=v;} public String getStationName(){return stationName;} public void setStationName(String v){stationName=v;} public String getProviderType(){return providerType;} public void setProviderType(String v){providerType=v;} public String getAccessType(){return accessType;} public void setAccessType(String v){accessType=v;} public String getAddress(){return address;} public void setAddress(String v){address=v;} public BigDecimal getLatitude(){return latitude;} public void setLatitude(BigDecimal v){latitude=v;} public BigDecimal getLongitude(){return longitude;} public void setLongitude(BigDecimal v){longitude=v;} public String getConnectorType(){return connectorType;} public void setConnectorType(String v){connectorType=v;} public BigDecimal getPowerKw(){return powerKw;} public void setPowerKw(BigDecimal v){powerKw=v;} public BigDecimal getPricePerKwh(){return pricePerKwh;} public void setPricePerKwh(BigDecimal v){pricePerKwh=v;} public boolean isActive(){return active;} public void setActive(boolean v){active=v;}
}
